select energy_manager.load_cards($cards$[
{"id":"p2-085","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What is a recuperator?","back":"A heat exchanger in which heat passes continuously from flue gas to combustion air through a separating metallic or ceramic wall.","explain":"Metallic radiation recuperators (concentric tubes) preheat combustion air from high-temperature flue gas; convective recuperators use tube banks. Ceramic tube recuperators handle higher gas temperatures (around 1550 °C) where metal would fail.","flash":false,"source":"BEE 2025 P2 Q3, L3","order":2084},
{"id":"p2-086","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What is a regenerator?","back":"A heat store (brick checkerwork) that is alternately heated by flue gas and then gives this heat to incoming cold air; two chambers operate in alternation.","explain":"Regenerators suit very high temperature, large furnaces such as glass furnaces and blast furnace stoves. Efficiency depends on the cycle reversal time and the heat capacity of the checkerwork.","flash":false,"source":"BEE 2025 P2 L3","order":2085},
{"id":"p2-087","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What are a heat wheel and a heat pipe?","back":"Heat wheel: a slowly rotating porous disc that transfers heat between two separate gas streams. Heat pipe: a sealed tube in which a working fluid evaporates at the hot end and condenses at the cold end, transferring heat with no moving parts.","explain":"Heat wheels suit low-to-medium temperature air streams such as HVAC exhaust. Heat pipes have very high effective conductance, need no external power and are compact and reliable.","flash":false,"source":"BEE 2025 P2 L3; BEE 2024 P2 L4","order":2086},
{"id":"p2-088","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"What does a heat pump do in waste heat recovery?","back":"It upgrades low-temperature waste heat to a higher useful temperature using mechanical (or thermal) work.","explain":"A heat pump works like a refrigeration cycle in reverse use: heat absorbed at the evaporator from a low-temperature source, plus compressor work, is delivered at the condenser at a higher temperature.","flash":false,"source":"BEE 2024 P2 Q4; BEE 2025 P2 L3","order":2087},
{"id":"p2-089","paper":2,"topic":"Waste heat recovery","kind":"fact","front":"How do multiple-effect evaporators save energy?","back":"Vapour produced in one effect is used as the heating steam for the next effect operating at lower pressure, so 1 kg of live steam evaporates several kg of water.","explain":"Each effect runs at lower pressure (and boiling point) than the previous one, allowing reuse of latent heat. Steam economy rises roughly in proportion to the number of effects, at the cost of more heat-transfer area.","flash":false,"source":"BEE 2024 P2 S7","order":2088},
{"id":"p2-090","paper":2,"topic":"Waste heat recovery","kind":"problem","front":"A hot effluent stream (5 kg/s, Cp 4.18 kJ/kg·K) at 90 °C preheats boiler make-up water (4 kg/s, Cp 4.18 kJ/kg·K) from 30 °C to 60 °C in a counter-flow heat exchanger with U = 900 W/m²·K. Neglecting losses, find (a) heat duty, (b) effluent exit temperature, (c) LMTD and required area, (d) effectiveness.","back":"(a) 501.6 kW; (b) 66.0 °C; (c) LMTD ≈ 32.9 °C, area ≈ 16.9 m²; (d) ε ≈ 50.0%","explain":"Heat gained by the cold stream equals heat lost by the hot stream. LMTD uses the two terminal temperature differences of the counter-flow arrangement, and area = Q/(U × LMTD). Effectiveness compares actual duty with the maximum possible, C_min × (T_h,in − T_c,in); here the water has the smaller capacity rate.","steps":[{"prompt":"Heat duty from the cold side.","answer":"Q = 4 × 4.18 × (60 − 30) = 501.6 kW","explain":"Q = m·Cp·ΔT."},{"prompt":"Effluent exit temperature.","answer":"T = 90 − 501.6/(5 × 4.18) = 66.0 °C","explain":"Energy balance on hot side."},{"prompt":"LMTD (counter-flow).","answer":"ΔT₁ = 90 − 60 = 30, ΔT₂ = 66.0 − 30 = 36.0; LMTD = (36.0 − 30)/ln(36.0/30) = 32.9 °C","explain":"LMTD = (ΔT₁ − ΔT₂)/ln(ΔT₁/ΔT₂)."},{"prompt":"Required area.","answer":"A = 501,600 / (900 × 32.9) = 16.9 m²","explain":"A = Q/(U·LMTD), Q in W."},{"prompt":"Effectiveness.","answer":"C_min = 4 × 4.18 = 16.72 kW/K; Q_max = 16.72 × (90 − 30) = 1,003.2 kW; ε = 501.6/1,003.2 = 50.0%","explain":"ε = Q/Q_max."}],"flash":false,"source":"Based on BEE 2025 P2 L1; BEE 2024 P2 S4","order":2089},
{"id":"p2-b01-001","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the density of a liquid fuel, at what reference temperature is it measured, and in what unit is it expressed?","back":"Density is the mass of fuel per unit volume at a reference temperature of 15 °C. It is measured with a hydrometer and expressed in kg/m³.","explain":"Density is used for quantity calculations and for assessing ignition quality. Because the value is tied to 15 °C, always quote the temperature with a density figure.","flash":false,"source":"BEE Book 2 Ch 01 p19","order":2090},
{"id":"p2-b01-002","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is specific gravity of a fuel oil, and does it have units?","back":"The ratio of the weight of a given volume of oil to the weight of the same volume of water at a given temperature. Water is 1, and specific gravity has no units.","explain":"Specific gravity is used in calculations that convert between weights and volumes. It is measured with a hydrometer; furnace oil is about 0.89 to 0.95.","flash":false,"source":"BEE Book 2 Ch 01 p19","order":2091},
{"id":"p2-b01-003","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How does viscosity change with temperature, and why must a viscosity figure always state its temperature?","back":"Viscosity decreases as temperature rises. A viscosity value has no meaning unless the temperature is also given.","explain":"Viscosity is a fluid's internal resistance to flow. It is measured in Stokes or centistokes (sometimes Engler, Saybolt or Redwood) with a viscometer, and each oil has its own temperature-viscosity relationship.","flash":false,"source":"BEE Book 2 Ch 01 p19","order":2092},
{"id":"p2-b01-004","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"Which calorific value should fuels be compared on, GCV or NCV, and why?","back":"Net calorific value (NCV). GCV assumes all water vapour formed in combustion is condensed, while NCV assumes the water leaves as vapour.","explain":"The difference between the two is the latent heat of condensation of the water vapour formed. The book recommends NCV because in practice the water leaves the stack uncondensed.","flash":false,"source":"BEE Book 2 Ch 01 p20","order":2093},
{"id":"p2-b01-005","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What formula converts NCV to GCV for a liquid fuel?","back":"GCV = NCV + 584 × (9H% + M%)/100, in kcal/kg. H% is hydrogen by weight, M% is moisture by weight, and 584 is the latent heat of water vapour in kcal/kg.","explain":"The 9H term counts the water formed when hydrogen burns: 4 kg of hydrogen gives 36 kg of water. The M term counts water already present in the fuel.","flash":false,"source":"BEE Book 2 Ch 01 p21","order":2094},
{"id":"p2-b01-006","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"A liquid fuel has an NCV of 10,000 kcal/kg, with 5% hydrogen and 2% moisture by weight. What is its GCV?","back":"About 10,274 kcal/kg (10,000 + 274.5).","explain":"This is an illustrative example built on the chapter's NCV-to-GCV formula, not a figure from the book. The latent heat term is 584 × 47/100, which is about 274.5 kcal/kg.","flash":false,"source":"BEE Book 2 Ch 01 p21","steps":[{"prompt":"Find 9H + M using H = 5 and M = 2.","answer":"9 × 5 + 2 = 47.","explain":"The formula's bracket term combines hydrogen and moisture."},{"prompt":"Convert the bracket term to a fraction and multiply by 584.","answer":"47/100 × 584 = 274.5 kcal/kg.","explain":"584 kcal/kg is the latent heat of the water vapour."},{"prompt":"Add the latent heat term to the NCV.","answer":"GCV = 10,000 + 274.5 = 10,274.5 kcal/kg.","explain":"GCV is always higher than NCV by the latent heat of the water formed."}],"order":2095},
{"id":"p2-b01-007","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the main disadvantage of sulphur in fuel oil?","back":"Corrosion. Sulphur forms sulphuric acid during and after combustion, which condenses in cool parts such as the chimney or stack, air preheater and economiser.","explain":"Furnace oil typically has 2 to 4% sulphur, while LSHS is below 0.5%. The risk is greatest at cool surfaces where the acid condenses.","flash":false,"source":"BEE Book 2 Ch 01 p21","order":2096},
{"id":"p2-b01-008","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How much furnace oil storage should be provided, and in what kind of tank?","back":"At least 10 days of normal consumption, in cylindrical tanks rather than barrels, with bund walls around the tanks to contain spillage.","explain":"Storing furnace oil in barrels is potentially hazardous. Industrial heating fuel tanks are usually vertical mild steel tanks mounted above ground.","flash":true,"source":"BEE Book 2 Ch 01 p22","order":2097},
{"id":"p2-b01-009","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How often should fuel oil storage tanks be cleaned?","back":"Annually for heavy fuels, and every two years for light fuels.","explain":"Solids and sludge settle in tanks over time. Fuel should also be free of dirt, sludge and water before it enters the combustion system.","flash":false,"source":"BEE Book 2 Ch 01 p22","order":2098},
{"id":"p2-b01-010","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"Why is a centrifugal pump not recommended for heavy fuel oil?","back":"As viscosity rises, a centrifugal pump's efficiency drops sharply and the horsepower it needs increases. Heavy fuel oils are best pumped with positive displacement pumps.","explain":"Positive displacement pumps can get cold, thick fuel moving. Light fuels suit centrifugal or turbine pumps, while piston or diaphragm pumps are used when higher pressures are needed.","flash":false,"source":"BEE Book 2 Ch 01 p23","order":2099},
{"id":"p2-b01-011","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"Below what ambient temperature does furnace oil become hard to pump?","back":"Below 25 °C.","explain":"The viscosity of furnace oil and LSHS rises as temperature falls, so the oil is preheated before pumping. This is done by heating the whole tank in bulk or by using an outflow heater.","flash":true,"source":"BEE Book 2 Ch 01 p24","order":2100},
{"id":"p2-b01-012","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"Which coal is geologically the oldest and which is the youngest?","back":"Anthracite is the oldest: hard, mostly carbon, with little volatile matter. Lignite is the youngest: soft, with high volatile matter and moisture.","explain":"The three main classes are anthracite, bituminous and lignite, with semi and sub grades in between. Bituminous and sub-bituminous coal are the common types used in Indian industry.","flash":false,"source":"BEE Book 2 Ch 01 p24","order":2101},
{"id":"p2-b01-013","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What four quantities does proximate analysis of coal report?","back":"Fixed carbon, volatile matter, ash and moisture, each as a percentage by weight.","explain":"Ultimate analysis instead gives each elemental constituent and needs a properly equipped laboratory. Proximate analysis needs only simple apparatus.","flash":false,"source":"BEE Book 2 Ch 01 p26","order":2102},
{"id":"p2-b01-014","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is volatile matter in coal, what is its typical range, and what does it do in combustion?","back":"The components that vaporise when coal is heated: combustible gases (methane, hydrocarbons, hydrogen, CO) and inert gases (CO₂, N₂). Typical range is 20 to 35%. It lengthens the flame, eases ignition and sets a minimum furnace height.","explain":"Volatile matter indicates how much gaseous fuel the coal contains. It also influences the secondary air requirement and how that air is distributed.","flash":false,"source":"BEE Book 2 Ch 01 p27","order":2103},
{"id":"p2-b01-015","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How does moisture in coal affect its heat content and combustion?","back":"It replaces combustible matter, so it lowers heat per kg. It also causes heat loss through evaporation and superheating of the vapour. Typical range is 0.5 to 10%.","explain":"Up to a limit, moisture helps bind fines and aids radiation heat transfer. Coal moisture still has to be transported, handled and stored.","flash":false,"source":"BEE Book 2 Ch 01 p27","order":2104},
{"id":"p2-b01-016","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"A 1% oxidation of coal has the same effect as what?","back":"1% ash in the coal.","explain":"Oxidation during storage counts as a loss just like ash, so coal should be kept from oxidising. Wind losses may add another 0.5 to 1.0% of the total loss.","flash":true,"source":"BEE Book 2 Ch 01 p28","order":2105},
{"id":"p2-b01-017","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What coal fineness is required for pulverised fuel firing?","back":"75% of the coal below 75 μm (micron).","explain":"One micron is 1/1000 mm. Other firing systems need coarser coal, such as 15 to 40 mm for chain grate stokers and under 10 mm for fluidised bed boilers.","flash":true,"source":"BEE Book 2 Ch 01 p30","order":2106},
{"id":"p2-b01-018","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"Why is coal conditioned with water before firing, and how should the water be added?","back":"Surface tension makes fines stick to larger lumps, so they do not fall through grate bars or get carried off by the draft. Moisture should be added uniformly, in a moving or falling stream of coal.","explain":"Wetting can also reduce unburnt carbon and the excess air needed when fines are very high. The book gives 4 to 5% surface moisture for coal with 10 to 15% fines.","flash":false,"source":"BEE Book 2 Ch 01 p30","order":2107},
{"id":"p2-b01-019","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"In what unit, and at what conditions, is the calorific value of a gaseous fuel expressed?","back":"kcal/Nm³, which is per normal cubic metre at 20 °C and 760 mm Hg.","explain":"LPG, natural gas, producer gas, blast furnace gas and coke oven gas are all quoted this way. Gaseous fuels are compared on NCV, since most gas appliances cannot use the heat in the water vapour formed.","flash":false,"source":"BEE Book 2 Ch 01 p31","order":2108},
{"id":"p2-b01-020","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How heavy is LPG vapour compared with air, and how much gas does liquid LPG produce on evaporation?","back":"Butane vapour is about twice as heavy as air and propane about 1.5 times. Liquid LPG evaporates to about 250 times its volume in gas.","explain":"The vapour sinks and can flow along the ground into drains before igniting far from the leak. LPG cylinders should not be stored in cellars or basements without ground-level ventilation.","flash":false,"source":"BEE Book 2 Ch 01 p32","order":2109},
{"id":"p2-b01-021","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the main constituent of natural gas, and what share of its volume is it?","back":"Methane, at about 95% of the total volume.","explain":"Other components include ethane, propane, butane, nitrogen and carbon dioxide, with traces of other gases. Natural gas is lighter than air and disperses quickly if it leaks.","flash":false,"source":"BEE Book 2 Ch 01 p32","order":2110},
{"id":"p2-b01-022","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How much heat is released per kg of carbon burned fully to CO₂, and per kg burned only to CO?","back":"CO₂: 8,084 kcal/kg of carbon. CO: 2,430 kcal/kg of carbon.","explain":"Burning carbon only to CO wastes 5,654 kcal per kg of carbon (8,084 − 2,430). This is why unburned carbon is the main concern for combustion efficiency.","flash":false,"source":"BEE Book 2 Ch 01 p34","order":2111},
{"id":"p2-b01-023","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What are the three T's of combustion?","back":"Temperature high enough to ignite and sustain combustion; Turbulence for intimate mixing of fuel and oxygen; and Time sufficient for complete combustion.","explain":"Controlling the three T's releases all the heat in the fuel. They are the levers that good combustion design and control work with.","flash":true,"source":"BEE Book 2 Ch 01 p34","order":2112},
{"id":"p2-b01-024","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"How much heat is lost for each kg of carbon that burns to CO instead of CO₂?","back":"About 5,654 kcal per kg of carbon (8,084 − 2,430).","explain":"Each kg of carbon sent to CO instead of CO₂ wastes heat that could have been used. The CO in flue gas is therefore a sign of lost fuel energy.","flash":false,"source":"BEE Book 2 Ch 01 p34","steps":[{"prompt":"Find the heat released when carbon burns fully to CO₂.","answer":"8,084 kcal/kg of carbon.","explain":"This is the full heat of carbon combustion."},{"prompt":"Find the heat released when carbon burns only to CO.","answer":"2,430 kcal/kg of carbon.","explain":"Partial combustion releases much less heat."},{"prompt":"Calculate the heat lost.","answer":"8,084 − 2,430 = 5,654 kcal per kg of carbon.","explain":"The book words this as per kg of CO formed; the subtraction is done per kg of carbon, which is the basis of the figures."}],"order":2113},
{"id":"p2-b01-025","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the main challenge in achieving combustion efficiency?","back":"Unburned carbon, which forms CO instead of CO₂ and is lost either in the ash or as incompletely burned gas.","explain":"Most boiler fuels allowed under current pollution standards contain little or no sulphur, and the hydrogen usually all burns. Controlling unburned carbon is therefore the main target.","flash":false,"source":"BEE Book 2 Ch 01 p35","order":2114},
{"id":"p2-b01-026","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"For 100 kg of furnace oil with C 85.9%, H 12%, O 0.7%, N 0.5% and S 0.5% by weight, how much theoretical air is needed per kg of fuel?","back":"About 14.12 kg of air per kg of fuel (1,412.45 kg per 100 kg of oil).","explain":"This is the chapter's lab-analysis example. Air is 23% oxygen by weight, so the net oxygen requirement is divided by 0.23.","flash":false,"source":"BEE Book 2 Ch 01 p37","steps":[{"prompt":"Find the oxygen needed for carbon.","answer":"85.9 × 2.667 = 229.07 kg O₂ (1 kg C needs 32/12 kg O₂).","explain":"12 kg of carbon needs 32 kg of oxygen to form 44 kg of CO₂."},{"prompt":"Find the oxygen needed for hydrogen.","answer":"12 × 8 = 96 kg O₂ (1 kg H needs 8 kg O₂).","explain":"4 kg of hydrogen needs 32 kg of oxygen to form 36 kg of water."},{"prompt":"Find the oxygen needed for sulphur.","answer":"0.5 × 1 = 0.5 kg O₂.","explain":"32 kg of sulphur needs 32 kg of oxygen to form 64 kg of SO₂."},{"prompt":"Net off the oxygen already in the fuel.","answer":"229.07 + 96 + 0.5 = 325.57 kg; less 0.7 kg in the fuel gives 324.87 kg O₂.","explain":"Oxygen already present in the fuel does not have to come from the air."},{"prompt":"Convert the oxygen requirement to air.","answer":"324.87 / 0.23 = 1,412.45 kg air per 100 kg fuel, which is 14.12 kg per kg of fuel.","explain":"Air is 23% oxygen by weight."}],"order":2115},
{"id":"p2-b01-027","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"For the furnace oil in the stoichiometric example (100 kg basis), what is the theoretical CO₂ content of dry flue gas by volume?","back":"About 15.6% by volume.","explain":"This is the highest CO₂ possible with no excess air. It is the reference value used to find excess air from a measured CO₂ reading.","flash":false,"source":"BEE Book 2 Ch 01 p37","steps":[{"prompt":"Find the moles of CO₂ in the flue gas.","answer":"314.97 kg / 44 = 7.16 kmol.","explain":"One kg mole of CO₂ weighs 44 kg."},{"prompt":"Find the moles of N₂ in the flue gas.","answer":"1,088.08 kg / 28 = 38.86 kmol, where 1,088.08 = 1,412.45 − 324.87 + 0.5 kg.","explain":"This is the nitrogen of the combustion air that passes through unreacted."},{"prompt":"Find the moles of SO₂.","answer":"1 kg / 64 = 0.016 kmol.","explain":"SO₂ is only a trace in this example."},{"prompt":"Calculate CO₂ by volume.","answer":"7.16 / (7.16 + 38.86 + 0.016) × 100 = 15.6%.","explain":"For dry gas, percentage by volume equals mole percentage."}],"order":2116},
{"id":"p2-b01-028","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"The measured CO₂ in flue gas is 10% and the theoretical CO₂ is 15.6%. What is the % excess air?","back":"About 52.4%.","explain":"A measured CO₂ below theoretical means extra air is being supplied. The chapter's relation for oil firing gives this value; the figures are those of the stoichiometric example.","flash":false,"source":"BEE Book 2 Ch 01 p38","steps":[{"prompt":"Write the relation for % excess air from CO₂ readings.","answer":"EA% = 7900 × (CO₂ theoretical − CO₂ actual) / [CO₂ actual × (100 − CO₂ theoretical)].","explain":"This is the oil-firing relation given in the chapter; the scanned formula was reconstructed from the worked numbers."},{"prompt":"Calculate the numerator.","answer":"7900 × (15.6 − 10) = 44,240.","explain":"Numerator uses the difference between theoretical and actual CO₂."},{"prompt":"Calculate the denominator.","answer":"10 × (100 − 15.6) = 844.","explain":"Denominator uses the actual CO₂ and the non-CO₂ share at theoretical."},{"prompt":"Find the excess air.","answer":"44,240 / 844 = 52.4%.","explain":"This matches the chapter's result."},{"prompt":"Check the total and excess air quantities.","answer":"Total air = 1,412.45 × 1.524 = 2,152.6 kg; excess = 740.1 kg per 100 kg fuel.","explain":"Excess air is the total air minus the theoretical air."}],"order":2117},
{"id":"p2-b01-029","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What CO₂ or O₂ level in flue gas indicates optimum combustion of fuel oil?","back":"CO₂ of 14 to 15%, or O₂ of 2 to 3%.","explain":"Measure CO₂ or O₂ with a continuous recorder, an Orsat apparatus or a portable fyrite. Figures 1.2 and 1.3 of the book then give the excess air level and stack losses.","flash":true,"source":"BEE Book 2 Ch 01 p39","order":2118},
{"id":"p2-b01-030","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the turndown ratio of a burner?","back":"The ratio of maximum to minimum fuel input without affecting the excess air level.","explain":"A burner with a maximum input of 250,000 kcal and a minimum of 50,000 kcal has a 5:1 turndown. At the highest turndown, extra excess air is often needed to keep mixing turbulent enough.","flash":false,"source":"BEE Book 2 Ch 01 p41","order":2119},
{"id":"p2-b01-031","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"A burner has a maximum input of 250,000 kcal and a minimum input of 50,000 kcal, with excess air held constant. What is its turndown ratio?","back":"5 to 1.","explain":"Turndown compares the maximum and minimum fuel inputs over which the excess air level is unchanged.","flash":false,"source":"BEE Book 2 Ch 01 p41","steps":[{"prompt":"Identify the maximum input.","answer":"250,000 kcal.","explain":"This is the top of the firing range."},{"prompt":"Identify the minimum input.","answer":"50,000 kcal.","explain":"This is the bottom of the firing range."},{"prompt":"Calculate the ratio.","answer":"250,000 / 50,000 = 5, so 5 to 1.","explain":"A higher ratio means a wider firing range."}],"order":2120},
{"id":"p2-b01-032","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How much air does 1 kg of coal typically need for complete combustion?","back":"About 7 to 8 kg of stoichiometric (theoretical) air, depending on its carbon, hydrogen, nitrogen, oxygen and sulphur content.","explain":"Coal cannot be burned on stoichiometric air alone; complete combustion always needs excess air. The amount needed depends on the firing equipment.","flash":true,"source":"BEE Book 2 Ch 01 p41","order":2121},
{"id":"p2-b01-033","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is clinker, and what causes it?","back":"A rough, hard, slag-like mass formed when coal ash with a low fusion temperature melts. Silica, calcium oxide and magnesium oxide in the ash lower the fusion point; Indian coal ash can fuse at about 1,100 °C.","explain":"Clinker sticks more readily to hot surfaces than cold ones, and to rough surfaces than smooth ones. Once formed, it tends to grow.","flash":false,"source":"BEE Book 2 Ch 01 p42","order":2122},
{"id":"p2-b01-034","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"How many kg of CO₂ and of water are produced by complete combustion of 1 kg of methane?","back":"About 2.75 kg of CO₂ and 2.25 kg of water.","explain":"Methane burns in fixed mass proportions: 16 kg of CH₄ gives 44 kg of CO₂ and 36 kg of water. The atomic weights used are C 12, O 16 and H 1.","flash":false,"source":"BEE Book 2 Ch 01 p42","steps":[{"prompt":"Write the combustion reaction.","answer":"CH₄ + 2O₂ → CO₂ + 2H₂O.","explain":"Natural gas is essentially pure methane."},{"prompt":"Write the molar masses that matter.","answer":"CH₄ = 16 kg; CO₂ = 44 kg; 2H₂O = 36 kg.","explain":"Mass ratios follow from the atomic weights."},{"prompt":"Find the CO₂ per kg of methane.","answer":"44 / 16 = 2.75 kg.","explain":"Each 16 kg of methane gives 44 kg of CO₂."},{"prompt":"Find the water per kg of methane.","answer":"36 / 16 = 2.25 kg.","explain":"The water comes from the hydrogen in the methane."}],"order":2123},
{"id":"p2-b01-035","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What is the stoichiometric air-to-natural-gas ratio by volume?","back":"About 9.5:1 to 10:1.","explain":"Gas ratios are stated by volume, not by weight. Natural gas is essentially pure methane, so its combustion is CH₄ + 2O₂ → CO₂ + 2H₂O.","flash":false,"source":"BEE Book 2 Ch 01 p42","order":2124},
{"id":"p2-b01-036","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What excess air level is typical for natural gas burners?","back":"About 5%.","explain":"Natural gas mixes readily with air and produces no smoke or soot, so it needs very little excess air. Among the fuels in this chapter, natural gas needs the least excess air.","flash":false,"source":"BEE Book 2 Ch 01 p44","order":2125},
{"id":"p2-b01-037","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"What are the two main types of draft in a combustion system?","back":"Natural draft, produced by the chimney alone from the weight difference between hot flue gas and outside air; and mechanical draft, produced artificially by fans.","explain":"Natural draft uses hand-operated dampers and no fans. Mechanical draft has three forms: balanced, induced and forced.","flash":false,"source":"BEE Book 2 Ch 01 p46","order":2126},
{"id":"p2-b01-038","paper":2,"topic":"Fuels & Combustion","kind":"fact","front":"How does balanced draft work, and what pressure does it hold in a boiler?","back":"A forced-draft fan pushes air into the furnace and an induced-draft fan draws gases out. The boiler is held 0.05 to 0.10 in. of water gauge below atmospheric pressure.","explain":"For reheating and heat-treatment furnaces the pressure is kept slightly positive instead. Induced draft alone keeps the furnace at slight negative pressure so that combustion air flows in.","flash":false,"source":"BEE Book 2 Ch 01 p46","order":2127},
{"id":"p2-b01-039","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"Estimate the combustion air per hour for 500 litres/hr of furnace oil (specific gravity 0.95; C 84%, H 12%, S 3%, O 1%) with 20% excess air.","back":"About 7,980 kg of air per hour (16.8 kg of air per kg of oil × 475 kg/hr).","explain":"Oxygen is needed for C, H and S, minus oxygen already in the fuel. Excess air is then added on top of the theoretical 14 kg of air per kg of oil.","flash":false,"source":"BEE Book 2 Ch 01 p47","steps":[{"prompt":"Convert the volume of oil to mass.","answer":"500 L/hr × 0.95 = 475 kg/hr.","explain":"Specific gravity links litres to kilograms."},{"prompt":"Find the oxygen needed for carbon.","answer":"0.84 × 32/12 = 2.24 kg O₂ per kg of fuel.","explain":"12 kg of carbon needs 32 kg of oxygen."},{"prompt":"Find the oxygen needed for hydrogen and sulphur.","answer":"H: 0.12 × 8 = 0.96 kg O₂ per kg of fuel. S: 0.03 × 1 = 0.03 kg O₂ per kg of fuel.","explain":"1 kg of hydrogen needs 8 kg of oxygen; 1 kg of sulphur needs 1 kg of oxygen."},{"prompt":"Net the oxygen and find the theoretical air.","answer":"2.24 + 0.96 + 0.03 − 0.01 = 3.22 kg O₂ per kg; air = 3.22 / 0.23 ≈ 14 kg per kg of fuel.","explain":"The 0.01 kg is oxygen already in the fuel, and air is 23% oxygen by weight."},{"prompt":"Add 20% excess air and multiply by the fuel mass.","answer":"Air = 14 × 1.2 = 16.8 kg/kg; total = 475 × 16.8 = 7,980 kg/hr.","explain":"Excess air covers imperfect mixing, so some is always needed beyond the theoretical amount."}],"order":2128}
]$cards$::jsonb);
